/** Per-scene, deduplicated GLB/glTF containers. Asset URLs and licenses belong to each game. */
export function createAssetLibrary({B,scene}){const pending=new Map(),loaded=new Set();let disposed=false;return{async load(url){if(disposed)throw Error('Asset library disposed');if(!pending.has(url)){const p=B.SceneLoader.LoadAssetContainerAsync('',url,scene).then(c=>{if(disposed){c.dispose();throw Error('Asset library disposed during load');}loaded.add(c);return c;}).catch(e=>{pending.delete(url);throw e;});pending.set(url,p);}return pending.get(url);},get size(){return loaded.size;},dispose(){if(disposed)return;disposed=true;for(const c of loaded)c.dispose();loaded.clear();pending.clear();}};}
